        text: `<strong>Что это:</strong> операционный день - один рабочий цикл платформы, от открытия до закрытия. Внутри дня проходят пять стадий, и на двух из них нужно подтверждение администратора. Вкладки раздела: Дашборд (текущий день и его стадии), Расхождения (сверка, которая нашла несходимости) и История (закрытые дни и снимки балансов).<br>
<strong>Зачем:</strong> чтобы остатки и операции платформы были согласованы на конец дня. Закрытый день - это зафиксированное состояние, на которое опираются отчеты и следующий день.<br>
<strong>Важно:</strong> вкладка Дашборд - точка входа в закрытие дня. Расхождения и История - то, что нужно проверить до и после закрытия.`,
