        heading: "Что это и зачем",
        text: `<strong>Что это:</strong> раздел двух вкладок. «Общие» задает повторы и уведомления. «Маршруты по умолчанию» задает цепочку провайдеров для каждой пары «валюта + рельс».<br>
<strong>Зачем:</strong> повторы убирают временные сбои провайдера без участия человека. Маршруты по умолчанию гарантируют, что платеж уйдет, даже если ни одно правило не подошло. Уведомления позволяют вовремя заметить сбой.<br>
<strong>Важно:</strong> маршруты по умолчанию получают все платежи без подходящего правила. Ошибка в них затрагивает весь поток по паре, поэтому изменения защищены причиной и кодом 2FA.`,
