    intro: "Счета банка у внешних провайдеров. Реальный счет — счет у провайдера, на который приходят и с которого уходят деньги клиентов. Корреспондентский (ностро) счет — собственный счет банка у провайдера или банка-корреспондента. Раздел показывает их остатки, реквизиты и связанные пользовательские счета.",
