        text: `<strong>Что это:</strong> реальные счета — записи о счетах банка у провайдеров. Для каждого указаны провайдер, валюта, реквизиты и фактический остаток. Ностро-счета — тот же объект, но с типом «корреспондентский»: это собственные деньги банка на счету у корреспондента.<br>
<strong>Зачем:</strong> клиентские деньги физически лежат на реальных счетах, а в системе учитываются на пользовательских (виртуальных) счетах. Раздел нужен, чтобы сверять эти два мира, знать, где лежат деньги и какими реквизитами пополнять, и выбирать счет для маршрутизации.<br>
<strong>Важно:</strong> реальный счет нельзя «пополнить» или «списать» из интерфейса. Движение денег возникает только из операций и проводок.`,
