        text: `<strong>Что это:</strong> операция — тип платежа или перевода, который можно включить в тариф. Домен (крипто или фиат), направление (исходящая, входящая, перевод, внутренний платёж) и то, откуда стартует поток (платформа или внешний инициатор).<br>
<strong>Зачем:</strong> лимиты и комиссии привязываются не к тарифу напрямую, а к связке «тариф + операция». Справочник операций задаёт, из чего можно собирать условия тарифа.<br>
<strong>Статус интеграции:</strong> показывает, учитывает ли реальный движок платежей лимиты этой операции полностью, частично или нет — это сигнал, что лимит в системе может быть только отображением, а не реальным ограничением.`,
