        text: `<strong>Взаимодействие с другими модулями:</strong> клиенты-физлица (статус KYC и уровень), конфигурации документов (шаг проверки документа ссылается на их настройки отдельно), аналитика пользователей.<br>
<strong>Запросы на бэк:</strong> список, карточка, создание новой версии, изменение общих полей (название, описание, родители) и изменение шага выполняются запросами к бэку.<br>
<strong>Граница прототипа:</strong> ==уточняется: как именно уровень и сервис определяют, какую конфигурацию получает конкретный клиент при онбординге==`,
